package com.dynasty;

import net.minecraft.ChatFormatting;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Player;

/**
 * 王朝玩家数值系统：官阶（功名）、忠诚、叛乱。
 * Dynasty player stats: official rank (merit), loyalty, rebellion. Stored in player persistent data.
 */
@SuppressWarnings("null")
public final class DynastyStats {

    private DynastyStats() {
    }

    private static final String RANK = "dynasty_rank";
    private static final String MERIT = "dynasty_merit";
    private static final String LOYALTY = "dynasty_loyalty";
    private static final String REBELLION = "dynasty_rebellion";

    /** 官阶名称（中文，20 阶，层层递进）。/ Rank names (Chinese, 20 steps). */
    public static final String[] RANK_ZH = {
            "布衣", "童生", "秀才", "举人", "贡士", "进士", "庶吉士", "编修", "侍读", "侍讲",
            "翰林", "侍郎", "尚书", "大学士", "太傅", "少师", "太师", "丞相", "摄政王", "天子"
    };

    /** 官阶名称（英文）。/ Rank names (English). */
    public static final String[] RANK_EN = {
            "Commoner", "Student", "Licentiate", "Provincial Graduate", "Tribute Student",
            "Metropolitan Graduate", "Hanlin Bachelor", "Compiler", "Imperial Reader", "Imperial Lecturer",
            "Hanlin Scholar", "Vice Minister", "Minister", "Grand Secretary", "Grand Tutor",
            "Junior Preceptor", "Grand Preceptor", "Chancellor", "Prince Regent", "Son of Heaven"
    };

    /**
     * 各阶所需功名（递增：每阶比上一阶多要 25 点）。
     * Merit needed for each rank; every step costs 25 more than the previous one.
     */
    public static final int[] RANK_THRESHOLDS = thresholds();

    private static int[] thresholds() {
        int[] out = new int[RANK_ZH.length];
        out[0] = 0;
        for (int i = 1; i < out.length; i++) {
            out[i] = out[i - 1] + 100 + 25 * (i - 1);
        }
        return out;
    }

    /** 功名 → 官阶 / merit to rank */
    public static int rankForMerit(int merit) {
        int rank = 0;
        for (int i = 1; i < RANK_THRESHOLDS.length; i++) {
            if (merit >= RANK_THRESHOLDS[i]) {
                rank = i;
            }
        }
        return rank;
    }

    /** 下一阶还需要多少功名（满阶返回 0）。/ merit still needed for the next rank */
    public static int meritToNext(Player player) {
        int rank = getRank(player);
        if (rank >= RANK_THRESHOLDS.length - 1) {
            return 0;
        }
        return Math.max(0, RANK_THRESHOLDS[rank + 1] - getMerit(player));
    }

    public static int getRank(Player player) {
        return player.getPersistentData().getInt(RANK);
    }

    public static int getMerit(Player player) {
        return player.getPersistentData().getInt(MERIT);
    }

    public static int getLoyalty(Player player) {
        return player.getPersistentData().getInt(LOYALTY);
    }

    public static int getRebellion(Player player) {
        return player.getPersistentData().getInt(REBELLION);
    }

    public static String rankName(Player player, boolean chinese) {
        int r = Math.max(0, Math.min(RANK_ZH.length - 1, getRank(player)));
        return chinese ? RANK_ZH[r] : RANK_EN[r];
    }

    public static void addMerit(ServerPlayer player, int amount) {
        int boosted = Math.round(amount * DynastyTrinkets.meritMultiplier(player));   // 金印饰品
        int merit = Math.max(0, getMerit(player) + boosted);
        player.getPersistentData().putInt(MERIT, merit);
        int newRank = rankForMerit(merit);
        int oldRank = getRank(player);
        if (newRank != oldRank) {
            player.getPersistentData().putInt(RANK, newRank);
            player.sendSystemMessage(Component.literal("§6[王朝] 官阶晋升：§e"
                    + RANK_ZH[newRank] + "§7 / " + RANK_EN[newRank]
                    + "§8（第 " + newRank + " 阶 / 功名 " + merit + "）"));
            player.addEffect(new net.minecraft.world.effect.MobEffectInstance(
                    DynastyEffects.MANDATE_OF_HEAVEN.get(), 20 * 120, 0));
            // 官阶越高，基础属性与饰品槽位越多 / higher rank grants stats and trinket slots
            DynastyRankPerks.apply(player);
            DynastyRankPerks.announce(player, newRank);
            DynastyAdvancements.awardForRank(player, newRank);
        }
        player.getPersistentData().putInt("dynasty_rank_notice", DynastyStats.meritToNext(player));
    }

    public static void addLoyalty(ServerPlayer player, int amount) {
        int v = Math.max(0, Math.min(100, getLoyalty(player) + amount));
        player.getPersistentData().putInt(LOYALTY, v);
    }

    public static void addRebellion(ServerPlayer player, int amount) {
        int v = Math.max(0, Math.min(100, getRebellion(player) + amount));
        player.getPersistentData().putInt(REBELLION, v);
        if (v >= 100) {
            player.sendSystemMessage(Component.literal("§c[王朝] 民怨沸腾！叛军即将出现……"));
        } else if (v >= 60) {
            player.sendSystemMessage(Component.literal("§e[王朝] 民心生变（叛乱 " + v + "%）"));
        }
    }

    public static void setRank(ServerPlayer player, int rank) {
        int r = Math.max(0, Math.min(RANK_ZH.length - 1, rank));
        player.getPersistentData().putInt(RANK, r);
        // 功名也要跟上，否则每秒的「按功名换算官阶」会把它退回去
        player.getPersistentData().putInt(MERIT, Math.max(getMerit(player), RANK_THRESHOLDS[r]));
    }

    public static void showStats(ServerPlayer player) {
        int rank = getRank(player);
        player.sendSystemMessage(Component.literal("§6===== 王朝档案 =====").withStyle(ChatFormatting.GOLD));
        player.sendSystemMessage(Component.literal("§7官阶：§f" + rankName(player, true)
                + " §8(" + RANK_EN[Math.min(RANK_EN.length - 1, rank)] + ")"
                + " §8第 " + rank + "/" + (RANK_ZH.length - 1) + " 阶"));
        player.sendSystemMessage(Component.literal("§7功名：§f" + getMerit(player)
                + (meritToNext(player) > 0
                   ? " §8（升下一阶还需 " + meritToNext(player) + "）" : " §8（已至顶阶）")));
        player.sendSystemMessage(Component.literal("§7忠诚：§f" + getLoyalty(player) + "§7%"));
        player.sendSystemMessage(Component.literal("§7叛乱：§f" + getRebellion(player) + "§7%"));
        player.sendSystemMessage(Component.literal("§7官阶加成：§f+" + DynastyRankPerks.bonusHealth(rank)
                + " 生命、§f+" + String.format("%.2f", DynastyRankPerks.bonusAttack(rank))
                + " 攻击、§f+" + String.format("%.2f", DynastyRankPerks.bonusArmor(rank))
                + " 护甲；§d任务万能槽 +" + DynastySlotProgression.bonusSlots(player)));
    }
}

package com.dynasty;

import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.EntityType;
import net.minecraftforge.registries.ForgeRegistries;

/**
 * 功名来源（任务只给一点点，主要靠打怪 / 与 NPC 交互 / 第一次获得新物品）。
 *
 * Merit sources: fights, NPC interaction and first-time item pickups. Quest rewards
 * only give a small amount, so ranks are earned by actually playing.
 */
@SuppressWarnings("null")
public final class DynastyMerit {

    private DynastyMerit() {
    }

    // ---- 与 NPC / 事件交互：每个事件只给一次 / one-off rewards
    private static final String FLAG = "dynasty_merit_evt_";

    public static void onEvent(ServerPlayer player, String key) {
        int amount = switch (key) {
            case "keju" -> 30;              // 科举答对
            case "minister" -> 15;          // 与大臣交谈
            case "army" -> 12;              // 虎符列阵
            case "qilin" -> 10;             // 喂麒麟
            case "dim_celestial" -> 40;     // 第一次到天朝
            case "dim_underworld" -> 40;    // 第一次到地府
            default -> 0;
        };
        if (amount <= 0 || player.getPersistentData().getBoolean(FLAG + key)) {
            return;
        }
        player.getPersistentData().putBoolean(FLAG + key, true);
        if (key.equals("minister") && com.dynasty.expansion.EquipmentBehaviors.pieces(player,"brocade")>=2) amount+=5;
        var ornaments=DynastyTrinkets.activeIds(player);
        if(ornaments.contains("gold_seal_charm") && !ornaments.contains("merit_badge")) amount=(int)Math.ceil(amount*1.2);
        DynastyStats.addMerit(player, amount);
        player.displayClientMessage(Component.literal("§6[功名] §r+" + amount + "（" + reason(key) + "）"), true);
    }

    private static String reason(String key) {
        return switch (key) {
            case "keju" -> "科举中第";
            case "minister" -> "拜见大臣";
            case "army" -> "列阵点兵";
            case "qilin" -> "祥瑞麒麟";
            case "dim_celestial" -> "登临天朝";
            case "dim_underworld" -> "初入地府";
            default -> "功勋";
        };
    }

    // ---- 击杀：滚怪也有功名，但每 10 分钟封顶，避免刷分 / kill merit, capped per 10 minutes
    private static final String KILL_WINDOW = "dynasty_merit_kill_window";
    private static final String KILL_EARNED = "dynasty_merit_kill_earned";
    private static final int KILL_CAP = 120;

    public static void onMobKill(ServerPlayer player, EntityType<?> type) {
        ResourceLocation id = ForgeRegistries.ENTITY_TYPES.getKey(type);
        if (id == null || !id.getNamespace().equals(Dynasty.MODID)) {
            return;
        }
        int amount = switch (id.getPath()) {
            case "dragon_emperor" -> 300;
            case "nine_heaven_general" -> 260;
            case "rebel_general", "eunuch_mastermind" -> 220;
            case "undead_first_emperor" -> 240;
            case "phoenix", "qilin" -> 60;
            case "nian_beast", "nine_tailed_fox" -> 40;
            case "assassin", "royal_guard" -> 12;
            case "archer", "imperial_soldier", "rebel_soldier", "terracotta_warrior" -> 5;
            default -> 0;
        };
        if (amount <= 0) {
            return;
        }
        // 小怪部分有 10 分钟上限（Boss 不受限）/ trash merit is capped
        if (amount < 100) {
            long now = System.currentTimeMillis();
            long window = player.getPersistentData().getLong(KILL_WINDOW);
            int earned = player.getPersistentData().getInt(KILL_EARNED);
            if (now - window > 10 * 60 * 1000L) {
                player.getPersistentData().putLong(KILL_WINDOW, now);
                earned = 0;
            }
            if (earned >= KILL_CAP) {
                return;
            }
            amount = Math.min(amount, KILL_CAP - earned);
            player.getPersistentData().putInt(KILL_EARNED, earned + amount);
        }
        DynastyStats.addMerit(player, amount);
    }

    // ---- 第一次获得某件王朝物品：每种一次 / first-time pickup merit
    private static final String SEEN = "dynasty_merit_seen_";

    public static void onFirstObtain(ServerPlayer player, String itemPath) {
        int amount = switch (itemPath) {
            case "dragon_crystal", "xuantian_jade", "dragon_emperor_seal", "emperor_bone" -> 25;
            case "jade", "phoenix_feather", "rebel_head", "eunuch_token", "sky_token" -> 12;
            case "jade_seal", "official_seal", "edict", "tiger_tally", "blueprint" -> 8;
            case "bronze_ingot", "silver_ingot", "refined_steel", "cinnabar" -> 5;
            default -> 0;
        };
        if (amount <= 0 || player.getPersistentData().getBoolean(SEEN + itemPath)) {
            return;
        }
        player.getPersistentData().putBoolean(SEEN + itemPath, true);
        amount=firstObtainAmount(DynastyTrinkets.activeIds(player),amount);
        DynastyStats.addMerit(player, amount);
        if(DynastyTrinkets.activeIds(player).contains("gold_seal_charm") && !DynastyTrinkets.activeIds(player).contains("merit_badge"))
            {com.dynasty.cod3.Cod3Vfx.send(player.serverLevel(),15,player.position(),player.getLookAngle(),16,.12,0xE7C866);com.dynasty.cod3.EquipmentFeedback.accessory(player,"gold_seal_charm");}
        player.displayClientMessage(Component.literal(
                "§6[功名] §r+" + amount + "（初次获得 " + itemPath + "）"), true);
    }
    /** First-pickup bonus is separate from the pre-existing global merit multiplier. */
    public static int firstObtainAmount(java.util.Set<String> active,int base){
        return active.contains("gold_seal_charm")&&!active.contains("merit_badge")?(int)Math.ceil(base*1.2):base;
    }
}

        net.minecraft.server.level.ServerBossEvent dynastyBossBar();
    }

    // ---------------------------------------------------------------- ③ 首杀奖励
    /** 首杀奖励表：Boss / 神兽 id → 功名 + 主题材料 / once-per-player first-kill table */
    private record FirstKill(int merit, String item, int count, String note) {
    }

    private static final Map<String, FirstKill> FIRST_KILL = new HashMap<>();

    static {
        FIRST_KILL.put("dragon_emperor",
                new FirstKill(400, "dragon_emperor_seal", 1, "龙帝玉玺到手：终盘装备的唯一凭据"));
        FIRST_KILL.put("undead_first_emperor",
                new FirstKill(300, "emperor_bone", 1, "帝骸骨到手：玄天 / 太乙系的强化材料"));
        FIRST_KILL.put("nine_heaven_general",
                new FirstKill(300, "sky_token", 1, "天界令牌到手：九霄的通行证"));
        FIRST_KILL.put("dragon_king",
                new FirstKill(320, "sea_token", 1, "龙宫令牌到手：龙鳞甲的前置"));
        FIRST_KILL.put("rebel_general",
                new FirstKill(240, "rebel_head", 1, "叛将首级到手：破军系兵器的前置"));
        FIRST_KILL.put("eunuch_mastermind",
                new FirstKill(240, "eunuch_token", 1, "内廷令牌到手：内造兵器的前置"));
        FIRST_KILL.put("phoenix", new FirstKill(120, "dragon_scale", 2, "凤凰羽落：龙鳞系材料"));
        FIRST_KILL.put("qilin", new FirstKill(120, "jade", 4, "麒麟献玉：玉料不愁"));
        FIRST_KILL.put("nian_beast", new FirstKill(100, "refined_steel", 3, "年兽镇宅：精钢入手"));
        FIRST_KILL.put("nine_tailed_fox", new FirstKill(100, "silk", 4, "狐尾丝线：织造材料"));
    }

    @SubscribeEvent
    public static void onDeath(LivingDeathEvent event) {
        if(com.dynasty.cod3.BossDeathState.managed(event.getEntity())
                && !event.getEntity().getPersistentData().getBoolean("dynasty_reward_granted"))return;
        if (event.getEntity().level().isClientSide()) {
            return;
        }
        ResourceLocation id = ForgeRegistries.ENTITY_TYPES.getKey(event.getEntity().getType());
        if (id == null || !id.getNamespace().equals(Dynasty.MODID)) {
            return;
        }
        if(event.getEntity().getPersistentData().hasUUID("ArmyEncounter"))return;
        LivingEntity credit = event.getEntity().getKillCredit();
        if (credit instanceof ServerPlayer player) grantFirstKill(player, id.getPath());
    }

    public static void awardFirstKill(ServerPlayer player, String bossId) { grantFirstKill(player, bossId); }

    public static void grantFirstKill(ServerPlayer player, String bossId) {
        FirstKill reward = FIRST_KILL.get(bossId);
        if (reward == null) return;
        String flag = "dynasty_firstkill_" + bossId;
        var persisted=player.getPersistentData().getCompound(net.minecraft.world.entity.player.Player.PERSISTED_NBT_TAG);
        player.getPersistentData().put(net.minecraft.world.entity.player.Player.PERSISTED_NBT_TAG,persisted);
        if (player.getPersistentData().getBoolean(flag)||persisted.getBoolean(flag)) {
            persisted.putBoolean(flag,true); // Migrate legacy receipts on their next check.
            return;                                        // 一种只给一次 / once per player
        }
        persisted.putBoolean(flag,true);
        player.getPersistentData().putBoolean(flag, true);

        DynastyStats.addMerit(player, reward.merit());
        ResourceLocation key = ResourceLocation.tryBuild(Dynasty.MODID, reward.item());
        Item item = key == null ? null : ForgeRegistries.ITEMS.getValue(key);
        if (item != null) {
            ItemStack stack = new ItemStack(item, reward.count());
            if (!player.getInventory().add(stack)) {
                player.drop(stack, false);
            }
        }
        player.displayClientMessage(Component.literal("§6[首杀] §r" + reward.note()
                + " §7(功名 +" + reward.merit() + ")"), false);
        player.playNotifySound(SoundEvents.UI_TOAST_CHALLENGE_COMPLETE, net.minecraft.sounds.SoundSource.MASTER,
                0.8F, 1.0F);
    }
}

package com.dynasty;

import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.ai.attributes.AttributeInstance;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;
import net.minecraft.world.entity.ai.attributes.Attributes;

import java.util.UUID;

/**
 * 官阶福利：官阶越高，基础属性越好。饰品加槽由任务里程碑独立管理。
 *
 * 每阶提供：+2 生命、+0.25 攻击、+0.25 护甲；
 * Rank perks grant attributes; quest milestones grant Curios slots.
 */
@SuppressWarnings("null")
public final class DynastyRankPerks {

    private DynastyRankPerks() {
    }

    private static final UUID HP_ID = UUID.fromString("d1a5c0de-0000-4000-8000-000000000001");
    private static final UUID ATK_ID = UUID.fromString("d1a5c0de-0000-4000-8000-000000000002");
    private static final UUID ARMOR_ID = UUID.fromString("d1a5c0de-0000-4000-8000-000000000003");

    public static int bonusHealth(int rank) {
        return rank * 2;
    }

    public static double bonusAttack(int rank) {
        return rank * 0.25D;
    }

    public static double bonusArmor(int rank) {
        return rank * 0.25D;
    }

    /** 应用（幂等）：属性按官阶刷新。 */
    public static void apply(ServerPlayer player) {
        // 老存档的官阶按新阶梯（20 阶）重新换算
        int expected = DynastyStats.rankForMerit(DynastyStats.getMerit(player));
        int rank = DynastyStats.getRank(player);
        if (expected != rank) {
            DynastyStats.setRank(player, expected);
            rank = expected;
        }
        set(player, Attributes.MAX_HEALTH, HP_ID, "dynasty_rank_health", bonusHealth(rank));
        set(player, Attributes.ATTACK_DAMAGE, ATK_ID, "dynasty_rank_attack", bonusAttack(rank));
        set(player, Attributes.ARMOR, ARMOR_ID, "dynasty_rank_armor", bonusArmor(rank));
        if (player.getHealth() > player.getMaxHealth()) {
            player.setHealth(player.getMaxHealth());
        }
    }

    private static void set(ServerPlayer player, net.minecraft.world.entity.ai.attributes.Attribute attribute,
                            UUID id, String name, double amount) {
        AttributeInstance instance = player.getAttribute(attribute);
        if (instance == null) {
            return;
        }
        AttributeModifier existing = instance.getModifier(id);
        if (existing != null) {
            if (existing.getAmount() == amount) {
                return;
            }
            instance.removeModifier(id);
        }
        if (amount != 0.0D) {
            instance.addPermanentModifier(new AttributeModifier(id, name, amount,
                    AttributeModifier.Operation.ADDITION));
        }
    }

    /** 官阶晋升时的提示 / message shown on rank up */
    public static void announce(ServerPlayer player, int newRank) {
        player.sendSystemMessage(Component.literal("§6[官阶福利] §r基础属性提升：§f+"
                + bonusHealth(newRank) + " 生命、+" + String.format("%.2f", bonusAttack(newRank))
                + " 攻击、+" + String.format("%.2f", bonusArmor(newRank)) + " 护甲"));
    }
}

package com.dynasty;

import com.dynasty.Dynasty;
import com.dynasty.entity.DynastyEntities;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.Mob;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.entity.living.LivingDeathEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

/**
 * 王朝世界事件：民怨叛乱、节日自动触发、战功（击杀奖励）。
 * Dynasty world events: rebellion uprisings, automatic festivals and battle merit rewards.
 */
@Mod.EventBusSubscriber(modid = Dynasty.MODID)
public class DynastyWorldEvents {

    private static int tickCounter = 0;

    @SubscribeEvent
    public static void onServerTick(TickEvent.ServerTickEvent event) {
        if (event.phase != TickEvent.Phase.END) {
            return;
        }
        if (++tickCounter < 200) {
            return;
        }
        tickCounter = 0;
        String festival = DynastyFestivals.today();
        for (ServerLevel level : event.getServer().getAllLevels()) {
            for (ServerPlayer player : level.players()) {
                // 1) 节日自动触发（每天一次）/ automatic festival, once per real day
                if (festival != null) {
                    String key = "dynasty_festival_day";
                    String stamp = festival + ":" + java.time.LocalDate.now();
                    if (!stamp.equals(player.getPersistentData().getString(key))) {
                        player.getPersistentData().putString(key, stamp);
                        DynastyFestivals.trigger(level, festival, player);
                    }
                }
                // 2) 叛乱爆发 / rebellion uprising
                int rebellion = DynastyStats.getRebellion(player);
                if (rebellion >= 100 && player.getRandom().nextInt(6) == 0) {
                    spawnRebellion(level, player);
                } else if (rebellion >= 60 && player.getRandom().nextInt(20) == 0) {
                    DynastyStats.addRebellion(player, 1);
                }
                // 3) 任务：维度探索 / quest: dimension visits
                var dim = level.dimension().location();
                if (dim.getNamespace().equals(com.dynasty.Dynasty.MODID)) {
                    if (dim.getPath().equals("celestial_dynasty")) {
                        DynastyAdvancements.awardForEvent(player, "dim_celestial");
                    } else if (dim.getPath().equals("underworld")) {
                        DynastyAdvancements.awardForEvent(player, "dim_underworld");
                    } else if (dim.getPath().equals("jiuxiao")) {
                        DynastyAdvancements.award(player, "entered_jiuxiao");
                    } else if (dim.getPath().equals("dragon_palace")) {
                        DynastyAdvancements.award(player, "entered_dragon_palace");
                    }
                }
                // 4) 饰品效果刷新 / refresh trinket effects
                DynastyTrinkets.tick(player);
                // 5) 官阶/民心类成就（FTB 任务书据此自动判定）/ derived advancement checks
                if (player.tickCount % 40 == 0) {
                    DynastyAdvancements.checkDerived(player);
                    DynastyWeaponGifts.tick(player);
                }
            }
        }
    }

    private static void spawnRebellion(ServerLevel level, ServerPlayer player) {
